// Worldwide country (ISO 3166-1) and currency (ISO 4217) data for DISH.
// Generated by scripts/build-geo.mjs from world-countries + currency-codes (+ CLDR names).
// Country and currency are independent: a country only *suggests* a currency.
import countries from '@/data/geo/countries.json'
import currencies from '@/data/geo/currencies.json'

export interface Country {
  c2: string // ISO 3166-1 alpha-2 (stored on the profile)
  c3: string // ISO 3166-1 alpha-3
  name: string
  flag: string
  cur: string[] // ISO 4217 codes used there, most common first
}
export interface Currency {
  code: string // ISO 4217 (stored on the profile)
  name: string
  symbol: string
  digits: number
}

export const COUNTRIES = countries as Country[]
export const CURRENCIES = currencies as Currency[]
export const DEFAULT_CURRENCY = 'USD' // fallback before a country is chosen

const byC2 = new Map(COUNTRIES.map((c) => [c.c2, c]))
const byCode = new Map(CURRENCIES.map((c) => [c.code, c]))

export const countryByCode = (c2: string | null | undefined) => (c2 ? (byC2.get(c2.toUpperCase()) ?? null) : null)
export const currencyByCode = (code: string | null | undefined) => (code ? (byCode.get(code.toUpperCase()) ?? null) : null)
export const isCurrency = (code: string | null | undefined) => !!currencyByCode(code)

/** Currencies associated with a country (may be several, may be none). */
export function countryCurrencies(c2: string | null | undefined): Currency[] {
  return (countryByCode(c2)?.cur ?? []).map((k) => byCode.get(k)).filter((c): c is Currency => !!c)
}

/** The currency DISH suggests for a country; USD when the country has none we can format. */
export function suggestedCurrency(c2: string | null | undefined): string {
  return countryCurrencies(c2)[0]?.code ?? DEFAULT_CURRENCY
}

/** Best guess of the user's country from the browser locale (a suggestion only). */
export function guessCountry(): string | null {
  try {
    const region = new Intl.Locale(navigator.language).maximize().region
    return region && byC2.has(region) ? region : null
  } catch {
    return null
  }
}

const fold = (s: string) => s.normalize('NFKD').replace(/[̀-ͯ]/g, '').toLowerCase()

export function searchCountries(q: string): Country[] {
  const t = fold(q.trim())
  if (!t) return COUNTRIES
  const starts: Country[] = []
  const contains: Country[] = []
  for (const c of COUNTRIES) {
    const n = fold(c.name)
    if (n.startsWith(t) || c.c2.toLowerCase() === t || c.c3.toLowerCase() === t) starts.push(c)
    else if (n.includes(t)) contains.push(c)
  }
  return [...starts, ...contains]
}

export function searchCurrencies(q: string): Currency[] {
  const t = fold(q.trim())
  if (!t) return CURRENCIES
  const exact = CURRENCIES.filter((c) => c.code.toLowerCase() === t)
  const rest = CURRENCIES.filter((c) => !exact.includes(c) && (fold(c.name).includes(t) || c.code.toLowerCase().startsWith(t) || c.symbol === q.trim()))
  return [...exact, ...rest]
}
